  igual(['2 kg de ração', 'Royal Canin 2 kg', 'Golden 15 kg', 'Premier 500 g', 'guia vermelha', 'Apoquel 16 mg'].map((t) => run(`ciPertTipo(${JSON.stringify(t)})`)),
    ['comida', 'comida', 'comida', 'comida', 'guia', 'outro']);
