    const r = res36(D, m);
    igual([r.aReceberTotal, r.declaradoTotal, r.inadimplenciaTotal, r.porFILHOt.length, r.semComoCalcular.length, r.inadimplentes.length], [0, 0, 0, 0, 0, 0], m);
    igual(ctx36.finBRL(r.aReceberTotal), 'R$ 0,00');
