    CARTEIRA_CARREGADA=true; pelCadCache=__cad644; PELUDINHOS=[]; recGuardarFontes(__orc644, {}); REC_MES='2026-07'; REC_AVULSO={mes:'', quando:0, lendo:false, ok:false, total_cent:0, n:0, semValor:0, futuros:0};
