  const D = dados36(cad36(S('2026-09-21', '2026-10-31', '2026-09-21'), { renov_hist: { a: hist644(S('2026-09-02', '2026-09-30', '2026-09-21'), 100) } }));
  const s9 = res36(D, '2026-09').porFILHOt.filter((o) => o.origem);
